        $lag=$this->db->row("SELECT COUNT(*) AS n,MIN(i.trigger_at) AS oldest FROM ".$this->db->table('notification_intents').' i JOIN '.$this->db->table('study_executions')." e ON e.id=i.execution_id WHERE $scope AND i.state IN ('PENDING','FAILED_RETRYABLE') AND i.trigger_at<UTC_TIMESTAMP()");$checks[]=array('check'=>'notification_queue','status'=>(int)$lag['n']?'PENDING':'OK','detail'=>$lag);
        $invalidVersions=$this->db->row('SELECT COUNT(*) AS n FROM '.$this->db->table('study_executions').' e LEFT JOIN '.$this->db->table('study_versions').' v ON v.id=e.study_version_id WHERE '.$scope.' AND (v.id IS NULL OR v.study_id<>e.study_id)');$checks[]=array('check'=>'participation_version_binding','status'=>(int)$invalidVersions['n']?'ERROR':'OK','detail'=>(int)$invalidVersions['n']);
        $jobs=$this->db->row('SELECT COUNT(*) AS n FROM '.$this->db->table('notification_intents').' i JOIN '.$this->db->table('study_executions').' e ON e.id=i.execution_id LEFT JOIN `'.$wpdb->prefix.'survey_nudge_jobs` j ON j.id=i.queue_job_id WHERE '.$scope.' AND i.queue_job_id IS NOT NULL AND j.id IS NULL');$checks[]=array('check'=>'notification_job_binding','status'=>(int)$jobs['n']?'ERROR':'OK','detail'=>(int)$jobs['n']);
        $journal=$this->db->row('SELECT COUNT(*) AS n FROM '.$this->db->table('submission_journal').' j JOIN '.$this->db->table('study_executions').' e ON e.id=j.execution_id LEFT JOIN `'.$wpdb->prefix.'vas_form_results` r ON r.id=CAST(SUBSTRING(j.local_storage_ref,14) AS UNSIGNED) WHERE '.$scope.' AND j.local_state=\'CONFIRMED\' AND j.local_storage_ref LIKE \'WORDPRESS_DB_%\' AND (r.id IS NULL OR r.session_id<>e.id)');$checks[]=array('check'=>'local_submission_binding','status'=>(int)$journal['n']?'ERROR':'OK','detail'=>(int)$journal['n']);
        if($this->nativeExists()){$sampleNative=$this->db->rows('SELECT n.id FROM '.$this->db->table('native_executions').' n JOIN '.$this->db->table('study_executions').' e ON e.id=n.management_execution WHERE '.$this->scope($f,true).' ORDER BY n.id LIMIT 100');$badNative=0;foreach($sampleNative as $n)try{$this->nativeRecord($n['id']);}catch(\Throwable $error){$badNative++;}$checks[]=array('check'=>'native_binding_sample','status'=>$badNative?'ERROR':'OK','detail'=>array('checked'=>count($sampleNative),'mismatches'=>$badNative,'sample_limit'=>100));}
        $checks[]=array('check'=>'storage_destination','status'=>'OK','detail'=>'WordPress local: Study y Native. Replicación externa no se infiere de la configuración global.');$checks[]=array('check'=>'worker_heartbeat','status'=>get_option('eipsi_management_worker_success')?'MEASURED':'NOT_MEASURED','detail'=>get_option('eipsi_management_worker_success',null));$checks[]=array('check'=>'backups_slow_queries_delivery','status'=>'NOT_MEASURED','detail'=>'Sin instrumentación de backups, consultas lentas o entrega/lectura SMTP.');
        $sample=$this->db->rows('SELECT e.id,e.study_version_id,e.checkpoint_hash,e.checkpoint_json FROM '.$this->db->table('study_executions').' e WHERE '.$scope.' ORDER BY e.id LIMIT 100');$bad=0;foreach($sample as $e){try{if(!$this->checkpointValid($e))$bad++;}catch(\Throwable $error){$bad++;}}$checks[]=array('check'=>'checkpoint_hash_sample','status'=>$bad?'ERROR':'OK','detail'=>array('checked'=>count($sample),'mismatches'=>$bad,'sample_limit'=>100));return array('checks'=>$checks,'as_of'=>gmdate('c'),'configuration_url'=>admin_url('admin.php?page=eipsi-configuration'));
    }
}
